<script setup lang="ts">
import {trackProductEvent} from '../analytics/product-events'
import {ref,computed,onMounted} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {api,newKey} from '../api'
import {useRequestScope} from '../platform/request-scope'
import {useApp} from '../stores/app'
import type {PlayControl} from './types'
import StateFields from '../authoring/StateFields.vue'
import {memoryDiff} from './memory-diff'
const props=defineProps<{kind:'lines'|'chats';identity:string}>(),emit=defineEmits<{saved:[model:string]}>(),capture=useRequestScope(()=>[props.kind,props.identity]),app=useApp(),value=ref<PlayControl>(),profile=ref<string|null>(null),summary=ref(''),notes=ref(''),busy=ref(false),error=ref(''),notice=ref(''),revision=ref(0),confirmReplace=ref<'load'|'restore'|null>(null)
const root=computed(()=>'/play-controls/'+props.kind+'/'+props.identity+'/settings'),dirty=computed(()=>!!value.value&&(profile.value!==value.value.profileId||summary.value!==value.value.memory.summary||notes.value!==value.value.memory.notes)),history=computed(()=>value.value?.history.find(h=>h.version===revision.value))
let intent:{body:string;key:string}|undefined
const closing=ref(false);let closeDecision:((allow:boolean)=>void)|undefined
function requestClose(){if(!dirty.value)return Promise.resolve(true);return new Promise<boolean>(resolve=>{closeDecision?.(false);closeDecision=resolve;closing.value=true})}
function decideClose(allow:boolean){closing.value=false;closeDecision?.(allow);closeDecision=undefined}
async function saveClose(){await save();if(!dirty.value&&!error.value)decideClose(true)}
defineExpose({requestClose})
onBeforeRouteLeave(()=>requestClose())
onBeforeRouteUpdate(()=>requestClose())
function apply(result:PlayControl){olderDone.value=false;value.value=result;profile.value=result.profileId;summary.value=result.memory.summary;notes.value=result.memory.notes;revision.value=result.history[0]?.version||0;confirmReplace.value=null}
async function load(){const scope=capture();busy.value=true;error.value='';try{const result=await api<PlayControl>(root.value);if(scope.valid())apply(result)}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function save(){if(!value.value||busy.value)return;const scope=capture(),body={expectedVersion:value.value.version,profileId:profile.value,summary:summary.value,notes:notes.value},serialized=JSON.stringify(body);if(intent?.body!==serialized)intent={body:serialized,key:newKey()};busy.value=true;error.value='';notice.value='';try{const result=await api<PlayControl>(root.value,{method:'PUT',body,key:intent.key});if(scope.valid()){apply(result);trackProductEvent('model.saved',{worldId:result.worldId,scope:props.kind});trackProductEvent('memory.saved',{worldId:result.worldId,scope:props.kind,version:result.version});intent=undefined;notice.value='已保存，从下一次提交开始使用。正在处理的请求继续使用提交时的模型与记忆。';emit('saved',result.effectiveModel?.name||'')}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function restore(){if(!value.value||!revision.value)return;const scope=capture();busy.value=true;error.value='';try{const result=await api<PlayControl>(root.value+'/restore',{method:'POST',key:newKey(),body:{expectedVersion:value.value.version,revision:revision.value}});if(scope.valid()){apply(result);notice.value='记忆已恢复并保存为新版本，模型选择保持当前设置。'}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
function request(action:'load'|'restore'){if(dirty.value)confirmReplace.value=action;else void(action==='load'?load():restore())}
function replace(){const action=confirmReplace.value;confirmReplace.value=null;void(action==='load'?load():restore())}
function factText(value:unknown):string{if(value==null)return '';if(typeof value==='string')return value;if(Array.isArray(value))return value.map(factText).filter(Boolean).join('\n');if(typeof value==='object')return Object.entries(value).filter(([key])=>!['id','checkpointId','resolvedAtCheckpointId'].includes(key)).map(([key,v])=>typeof v==='string'?v:factText(v)).filter(Boolean).join('\n');return ''}
const generationState=(state:string)=>({queued:'等待开始',preparing:'正在准备',calling:'正在生成',running:'正在生成',streaming:'正在生成',validating:'正在核对',saving:'正在保存',succeeded:'已完成',failed:'未完成',cancelled:'已停止'} as Record<string,string>)[state]||'正在处理'
const panel=ref('memory'),sourceSearch=ref(''),olderBusy=ref(false),olderDone=ref(false)
const chosen=computed(()=>value.value?.models.find(m=>m.id===(profile.value||(value.value?.defaultModelId??value.value?.effectiveModel?.id)))),episodes=computed(()=>value.value?.episodes?.filter(e=>!sourceSearch.value||(e.title+' '+e.text).includes(sourceSearch.value))||[]),summaryDiff=computed(()=>memoryDiff(history.value?.memory.summary||'',summary.value)),notesDiff=computed(()=>memoryDiff(history.value?.memory.notes||'',notes.value))
async function olderHistory(){if(!value.value?.history.length||olderBusy.value)return;const scope=capture();olderBusy.value=true;try{const result=await api<{items:PlayControl['history'];nextBefore:number|null}>(root.value.replace(/\/settings$/,'')+'/history?before='+value.value.history.at(-1)!.version);if(scope.valid()){value.value.history=[...value.value.history,...result.items.filter(i=>!value.value!.history.some(r=>r.version===i.version))];olderDone.value=result.nextBefore===null}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())olderBusy.value=false}}
onMounted(load)
</script>

<template>
<div class="play-settings">
 <section v-if="closing" role="alert"><p>模型与记忆还有未保存修改。</p><button class="primary" :disabled="busy" @click="saveClose">保存后离开</button><button :disabled="busy" @click="decideClose(true)">放弃修改并离开</button><button @click="decideClose(false)">继续编辑</button></section>
 <p class="product-hint">{{kind==='lines'?'仅用于当前开局，不改变账号默认模型。':'仅用于这段独立对话，不改变游玩模型。'}}记忆是叙事提醒，物品归属、人物已知范围与结局仍以正式记录为准。</p>
 <p v-if="error" role="alert" class="error">{{error}} <button :disabled="busy" @click="request('load')">载入最新版本</button></p><p v-if="notice" role="status">{{notice}}</p><p v-if="!value&&!error" role="status">正在读取模型与记忆…</p>
 <template v-if="value">
 <nav class="memory-tabs" aria-label="模型与记忆分类"><button v-for="[id,label] in [['models','模型与预算'],['memory','叙事记忆'],['sources','章节与来源'],['versions','历史与恢复']]" :key="id" :aria-pressed="panel===id" @click="panel=id">{{label}}</button></nav>
 <fieldset :disabled="busy">
 <section v-show="panel==='models'"><h2>文本模型</h2><p>当前生效：<strong>{{value.effectiveModel?.name||'暂不可用'}}</strong></p><label>这次{{kind==='lines'?'游玩':'对话'}}使用的模型<select aria-label="本次文本模型" v-model="profile"><option :value="null">跟随账号默认</option><option v-for="model in value.models" :key="model.id" :value="model.id" :disabled="!model.available">{{model.name}} · {{model.available?'可用':'不可用'}}</option></select></label><p v-if="value.modelUnavailable" class="error">已选模型不可用，请重新选择后保存。</p>
 <article v-if="chosen" class="model-info"><h3>{{chosen.name}}</h3><p>{{chosen.source==='platform'?'平台通道':'个人配置通道'}} · 上下文 {{chosen.contextWindow?.toLocaleString()||'未提供'}} tokens</p><p v-if="chosen.remainingInputTokens!==undefined">通道剩余：{{chosen.remainingCalls===null?'调用次数不限':chosen.remainingCalls+' 次调用'}}；输入 {{chosen.remainingInputTokens===null?'不限':chosen.remainingInputTokens.toLocaleString()}}、输出 {{chosen.remainingOutputTokens===null?'不限':chosen.remainingOutputTokens?.toLocaleString()}} tokens。</p><p v-if="chosen.reservation">单次文字行动最多预留 {{chosen.reservation.maxCalls}} 次调用、{{chosen.reservation.inputTokens.toLocaleString()}} 输入和 {{chosen.reservation.outputTokens.toLocaleString()}} 输出 tokens。</p><p>这些是通道额度和安全预留上限，不是本次价格。实际用量以任务回执为准；未提供可核验单价时，金额保持未知。</p><details><summary>模型标识</summary><code>{{chosen.modelId}}</code></details></article>
 <span class="muted">模型与用量由账号服务管理</span><p>仅显示当前账号实际可用的通道；图像和视觉校验通道分开管理。</p></section>
 <section v-show="panel==='memory'"><h2>叙事记忆</h2><p class="muted">整理摘要与称呼、语气等提醒；不能在这里修改已经确认的物品、人物知识和结局。</p><label>叙事摘要<textarea aria-label="叙事摘要" v-model="summary" rows="6" maxlength="4000" placeholder="整理你希望保留的背景与叙事重点"></textarea></label><label>补充提醒<textarea aria-label="补充提醒" v-model="notes" rows="4" maxlength="4000" placeholder="例如称呼、语气与值得继续追踪的问题"></textarea></label><button @click="panel='sources'">对照章节与人物来源</button></section>
 <section v-show="panel==='sources'"><h2>章节与来源</h2><p class="play-memory-text">{{value.automaticSummary||'尚无自动摘要'}}</p>
 <article v-if="value.generationContext" class="generation-context"><h3>最近一次生成使用的记忆</h3><p>{{value.generationContext.modelName||'提交时的文本模型'}} · 记忆版本 {{value.generationContext.memoryVersion}} · {{generationState(value.generationContext.state)}}</p><p>已排队或完成的请求保留提交时的版本。现在保存不会改写它。</p><details><summary>查看当时的摘要与提醒</summary><p>{{value.generationContext.memory.summary||'当时未填写摘要'}}</p><p>{{value.generationContext.memory.notes||'当时未填写提醒'}}</p></details><span>生成回执由任务服务保留</span></article>
 <label>查找来源章节<input v-model="sourceSearch" type="search" placeholder="章节标题、约定或人物"></label><p v-if="!episodes.length">没有匹配的来源记录。新开局完成后会显示章节；独立聊天积累较早消息后会显示召回摘录。</p><article v-for="episode in episodes" :key="episode.checkpointId+':'+episode.sequence" class="memory-source"><h3>{{episode.title||'来源记录'}}</h3><p>{{episode.text}}</p><RouterLink v-if="episode.href" :to="episode.href">{{episode.kind==='chat'?'定位原消息':'打开原章节'}}</RouterLink></article>
 <details><summary>查看已确认的经历与人物</summary><p class="play-memory-text">{{factText(value.confirmedFacts)}}</p><article v-for="character in value.characters" :key="character.id"><h3>{{character.name}}</h3><p>{{character.description}}</p><StateFields v-if="character.fields" :fields="value.fieldDefinitions" :values="character.fields"/><p v-for="fact in character.knownFacts" :key="fact.title"><strong>{{fact.title}}</strong> · {{fact.text}}</p></article></details></section>
 <section v-show="panel==='versions'"><h2>历史与恢复</h2><p v-if="!value.history.length">保存后会记录历史版本。</p><template v-else><button v-if="value.history.length>=50&&!olderDone" :disabled="olderBusy" @click="olderHistory">查看更早的记忆版本</button><label>记忆历史<select aria-label="记忆历史" v-model="revision"><option v-for="item in value.history" :key="item.version" :value="item.version">版本 {{item.version}} · {{new Date(item.createdAt).toLocaleString()}}</option></select></label><div v-if="history" class="memory-comparison"><article><h3>选中历史版本</h3><strong>摘要</strong><p>{{history.memory.summary||'未填写'}}</p><strong>提醒</strong><p>{{history.memory.notes||'未填写'}}</p></article><article><h3>当前编辑内容</h3><strong>摘要</strong><p>{{summary||'未填写'}}</p><strong>提醒</strong><p>{{notes||'未填写'}}</p></article></div><section v-if="!summaryDiff.same||!notesDiff.same" class="memory-change"><h3>恢复时替换的范围</h3><p v-if="!summaryDiff.same">摘要：当前 <del>{{summaryDiff.added||'（空）'}}</del> → 历史 <ins>{{summaryDiff.removed||'（空）'}}</ins></p><p v-if="!notesDiff.same">提醒：当前 <del>{{notesDiff.added||'（空）'}}</del> → 历史 <ins>{{notesDiff.removed||'（空）'}}</ins></p></section><p v-else>此版本与当前记忆内容一致。</p><p>恢复会保存为新版本，保留当前模型。主线与结局不变，下一次提交从恢复后的提醒继续。</p><button :disabled="!revision||!app.online" @click="request('restore')">恢复这个记忆版本</button></template></section>
 <footer class="memory-save"><small role="status">{{dirty?'有未保存修改':'已与保存版本一致'}} · 当前记忆版本 {{value.version}}</small><button class="primary" :disabled="!dirty||!app.online" @click="save">{{busy?'正在保存…':'保存模型与记忆'}}</button><button v-if="panel!=='memory'" @click="panel='memory'">继续编辑记忆</button></footer>
 </fieldset><section v-if="confirmReplace" role="alert"><p>当前还有未保存修改，{{confirmReplace==='load'?'载入最新版本':'恢复历史'}}会替换这些内容。</p><button @click="replace">确认替换</button><button @click="confirmReplace=null">继续编辑</button></section>
 </template>
</div>
</template>
<style scoped>.play-settings{min-width:0}.play-settings fieldset{border:0;padding:0;min-width:0}.play-settings label{display:block;margin:18px 0}.play-settings textarea,.play-settings select,.play-settings input{width:100%;min-height:44px;max-width:100%}.play-settings button{min-height:44px;margin:4px}.play-settings h2{margin-top:24px}.play-settings details{margin-top:16px}.play-settings summary{cursor:pointer;min-height:44px}.play-memory-text,.memory-comparison p,.memory-source p,.generation-context p,.memory-change{white-space:pre-wrap;overflow-wrap:anywhere}.memory-tabs{display:flex;flex-wrap:wrap;gap:4px}.memory-tabs [aria-pressed=true]{border-color:var(--accent,#b56229);background:var(--accent-soft,#b5622910)}.model-info,.memory-source,.generation-context,.memory-comparison article{border:1px solid var(--line,#e8e1d8);border-radius:12px;padding:16px;margin:16px 0}.memory-comparison{display:grid;grid-template-columns:1fr 1fr;gap:12px}.memory-save{border-top:1px solid var(--line,#e8e1d8);padding:16px 0;margin-top:24px}.memory-change ins{color:var(--ink,#252923);background:#74a56330;text-decoration:none}.memory-change del{background:#cf8b7930}.play-settings small{display:block}@media(max-width:650px){.memory-comparison{grid-template-columns:1fr}}</style>
